export function evaluate({ inputs }) {
  const eta = parseFloat(inputs.eta);
  const n = Math.round(sdk.clamp(inputs.step, 0, 8));
  const f = 1 - eta;
  const ws = [3];
  for (let k = 1; k <= 8; k++) ws.push(ws[k - 1] * f);
  const X = sdk.linear([-7, 7], [60, 600]);
  const Y = sdk.linear([0, 25], [470, 50]);
  const SX = sdk.linear([0, 8], [690, 930]);
  const SY = sdk.linear([-7, 7], [290, 70]);
  const o = [];
  o.push(sdk.line('ax', 60, 470, 600, 470));
  o.push(sdk.line('ay', X(0), 470, X(0), 50));
  [-6, -3, 3, 6].forEach(v => o.push(sdk.text('tx' + v, X(v), 492, String(v), { align: 'middle' })));
  [12, 24].forEach(v => o.push(sdk.text('ty' + v, X(0) - 10, Y(v) + 4, String(v), { align: 'middle' })));
  o.push(sdk.text('xl', 600, 492, 'w', { align: 'middle' }));
  o.push(sdk.math('title', 70, 36, 'L(w) = \\tfrac{1}{2}w^2'));
  const curve = sdk.sample(w => w * w / 2, -7, 7, 140).map(p => [X(p[0]), Y(p[1])]);
  o.push(sdk.polyline('curve', curve, { role: 'neutral' }));
  const pts = ws.slice(0, n + 1).map(w => [X(w), Y(w * w / 2)]);
  if (pts.length > 1) o.push(sdk.polyline('path', pts, { role: 'learner' }));
  pts.forEach((p, k) => o.push(sdk.circle('p' + k, p[0], p[1], k === n ? 14 : 9, { role: k === n ? 'prediction' : (k === 0 ? 'input' : 'learner') })));
  // side plot
  o.push(sdk.line('sax', 690, SY(0), 930, SY(0)));
  o.push(sdk.line('say', 690, 70, 690, 290));
  o.push(sdk.text('st', 690, 56, 'w against step k', {}));
  o.push(sdk.text('s6', 676, SY(6) + 4, '6', { align: 'middle' }));
  o.push(sdk.text('sm6', 672, SY(-6) + 4, '-6', { align: 'middle' }));
  o.push(sdk.text('s0', 676, SY(0) + 4, '0', { align: 'middle' }));
  o.push(sdk.text('sk8', 930, 310, '8', { align: 'middle' }));
  o.push(sdk.text('sk0', 690, 310, 'k = 0', { align: 'middle' }));
  const sp = ws.slice(0, n + 1).map((w, k) => [SX(k), SY(w)]);
  if (sp.length > 1) o.push(sdk.polyline('spath', sp, { role: 'learner' }));
  sp.forEach((p, k) => o.push(sdk.circle('s' + 'p' + k, p[0], p[1], k === n ? 11 : 7, { role: k === n ? 'prediction' : 'learner' })));
  const w = ws[n], L = w * w / 2;
  o.push(sdk.math('rule', 660, 350, 'w_{k+1} = w_k - \\eta\\,w_k = (1-\\eta)\\,w_k'));
  o.push(sdk.text('fac', 660, 385, 'eta = ' + eta + ', factor 1 - eta = ' + sdk.format(f, 1)));
  o.push(sdk.text('cur', 660, 412, 'step ' + n + ': w = ' + sdk.format(w, 3) + ', L = ' + sdk.format(L, 3)));
  const msg = eta === 0.2 ? 'Slides down slowly: factor 0.8' : eta === 0.8 ? 'Drops in fast, no overshoot: factor 0.2' : eta === 1.2 ? 'Overshoots, jumps shrink: |-0.2| < 1' : 'Overshoots, jumps grow: |-1.1| > 1, diverges';
  o.push(sdk.text('msg', 660, 440, msg, { role: eta === 2.1 ? 'warning' : 'success' }));
  o.push(sdk.text('rule2', 660, 468, 'Settles only if -1 < 1 - eta < 1'));
  return { frame: sdk.frame(o, { width: 960, height: 540, readouts: [{ id: 'w_now', value: w }, { id: 'loss_now', value: L }, { id: 'factor', value: f }] }), quantities: { w: w, loss: L, factor: f, step: n } };
}

